"""도로 / 차량 / 배경 교통류 설정 파일.

이 파일의 값을 수정한 뒤 train.py를 다시 실행하면
road_builder.py가 SUMO 도로 파일(.net.xml 등)을 자동으로 다시 만들어준다.
즉, 도로를 바꾸고 싶으면 이 파일만 고치면 된다.

단위 참고:
    - 거리: m (미터)
    - 속도: m/s  (참고: 13.89 m/s = 50 km/h,  16.67 m/s = 60 km/h)
    - 방위각: 도(°). 북 = 0, 시계방향으로 증가 (동 = 90, 남 = 180, 서 = 270)
"""

# ──────────────────────────────────────────────────────────────
# 1) 도로 형상 — 부산 연산교차로 (연제구 연산동)
#
#    6개 도로가 한 점에 모이는 방사형 교차로(옛 연산로터리).
#    각 도로는 왕복 분리 도로(진입/진출 따로)이고, 바깥쪽에는
#    이웃한 도로끼리 이어지는 "우회전 전용 연결로" 6개가 고리처럼 둘러져 있다.
#
#                  N 중앙대로(동래 방면)
#                      │      ╱ NE 반송로
#  W 월드컵대로 ───────  ●  ───── E 고분로
#                    ╱    ╲
#   SW 중앙대로(서면 방면)    S 월드컵대로
#
#    방위각은 OpenStreetMap 도로 데이터에서 교차점 기준 100~300m 지점을
#    측정한 값이다. 차로 수는 OSM 태그 값이고, 태그가 없는 도로(반송로,
#    고분로)는 왕복 4차로로 가정했다. 실제 차로 수는 지도 로드뷰로 확인 후
#    고칠 것. 중앙대로의 BRT 전용차로는 일반 차로에 포함하지 않았다.
#
#    교통량(inflow)은 실측값이 아니라, 신호 1주기 동안 처리 가능한 양의
#    약 60~70% 수준으로 잡은 값이다 (넘치면 대기열이 끝없이 늘어난다).
#
#    road_builder.py는 "legs"가 있으면 env/junction_builder.py로
#    방사형 교차로를 만든다. legs를 바꾸면 다른 다지 교차로도 만들 수 있다.
# ──────────────────────────────────────────────────────────────
ROAD = {
    "name": "부산 연산교차로",
    "speed_limit": 13.89,   # 제한속도 50 km/h (도심 안전속도 5030).
                            # ego 최고속도이자 관측/보상의 속도 정규화 기준(vmax)
    "split_dist": 70.0,     # 교차점 ~ 우회전 연결로 분기/합류 지점 거리 (m).
                            # 교차로 면적 바깥에 진입 구간이 20m 이상 남도록 잡음
    "junction_radius": 25.0,  # 교차점 모서리 회전 반경 (m). 클수록 교차로 면적이
                              # 넓어진다. 25 → 교차로 지름 약 70~88m
                              # (지도 기준 실제 교차로 지름 약 80m)
    "median": 2.0,          # 중앙분리대 폭 (m)
    "slip_lanes": True,     # 우회전 전용 연결로 사용 여부

    # ── 주변 도로망까지 실제 지도로 만들기 (env/osm_builder.py) ──
    # enabled=True : OpenStreetMap 데이터로 교차로 주변 약 1km × 1km의
    #                실제 도로망(이면도로·주변 신호 포함)을 만든다.
    # enabled=False: 아래 legs로 연산교차로 하나만 단순화해서 만든다
    #                (env/junction_builder.py, 우회전 연결로/신호 직접 생성).
    "osm": {
        "enabled": True,
        "file": "env/osm/yeonsan.osm",          # OSM 원본 (저장소에 포함)
        "bbox": [129.0765, 35.1815, 129.0870, 35.1905],  # 서,남,동,북 경도/위도
        "center_node": "414663644",             # OSM의 연산교차로 노드 id
        "buildings": True,       # 건물 표시 (GUI 배경, 학습과 무관)
        "side_inflow": 30.0,     # 골목길 입구 1곳당 들어오는 교통량 (대/시간)
        "side_share": 0.1,       # 간선 교통량 중 골목길로 빠지는 비율
        "ego_approach": 400.0,   # ego 출발 위치: 교차점까지 경로상 거리 (m)
    },
    # id     : 도로 식별자 (엣지 이름에 쓰임: in_N, out_N, ...)
    # bearing: 교차점에서 그 도로 쪽을 바라본 방위각
    # length : 교차점에서 도로 끝까지 길이 (m)
    # lanes_in / lanes_out : 교차로로 들어오는 / 나가는 방향 차로 수
    # green  : 이 도로 진입 차량의 녹색 신호 시간 (s)
    # inflow : 이 도로로 들어오는 배경 교통량 (대/시간)
    "legs": [
        dict(id="N", road="중앙대로",  name="중앙대로 (동래 방면)", bearing=348.0, length=300.0,
             lanes_in=2, lanes_out=2, green=25.0, inflow=420),
        dict(id="NE", road="반송로", name="반송로",               bearing=46.0,  length=250.0,
             lanes_in=2, lanes_out=2, green=15.0, inflow=220),
        dict(id="E", road="고분로",  name="고분로",               bearing=100.0, length=250.0,
             lanes_in=2, lanes_out=2, green=15.0, inflow=220),
        dict(id="S", road="월드컵대로",  name="월드컵대로 (남쪽)",    bearing=158.0, length=300.0,
             lanes_in=3, lanes_out=3, green=25.0, inflow=560),
        dict(id="SW", road="중앙대로", name="중앙대로 (서면 방면)", bearing=217.0, length=400.0,
             lanes_in=2, lanes_out=2, green=25.0, inflow=420),
        dict(id="W", road="월드컵대로",  name="월드컵대로 (사직 방면)", bearing=293.0, length=300.0,
             lanes_in=4, lanes_out=3, green=25.0, inflow=700),
    ],
}

# ──────────────────────────────────────────────────────────────
# 1-1) 교차로 신호등
#    도로별 "동시신호": 한 번에 한 도로의 진입 차량만 녹색을 받아
#    직진·좌회전·우회전을 모두 한다 (legs 순서대로 돌아감).
#    각 녹색 뒤에 황색 → 전적색이 붙는다.
#    기본값 기준 1주기 = (25×4 + 15×2) + 6×(3+2) = 160초.
#    우회전 연결로는 신호 없이 합류 지점에서 양보한다.
# ──────────────────────────────────────────────────────────────
SIGNAL = {
    "enabled": True,
    "yellow": 3.0,         # 황색 시간 (s). 50 km/h 정지거리 ≈ 18m
    "all_red": 2.0,        # 전적색 시간 (s). 넓은 교차로를 비우는 시간
}

# ──────────────────────────────────────────────────────
# 도로변 장식 (순수 시각 요소 — 직선 도로 예제에서만 사용)
# ──────────────────────────────────────────────────────
SCENERY = {
    "trees": True,          # 나무 심기 on/off
    "tree_spacing": 45.0,   # 같은 쪽 나무 사이 평균 간격 (m)
    "tree_jitter": 0.5,     # 간격/위치의 무작위 흔들림 비율
    "side_offset": 6.0,     # 도로 가장자리에서 나무까지 거리 (m)
    "seed": 7,              # 배치 난수 시드 (매번 같은 숲)
}

# ──────────────────────────────────────────────────────────────
# 2) ego 차량 (RL 에이전트가 조종하는 빨간 차)
#    accel/decel은 행동 a=±1일 때의 가감속 크기다.
# ──────────────────────────────────────────────────────────────
EGO = {
    "accel": 3.0,          # 최대 가속도 (m/s^2)  → 행동 a=+1 일 때
    "decel": 5.0,          # 최대 감속도 (m/s^2)  → 행동 a=-1 일 때
    "max_speed": 13.89,    # 차량 자체의 최고속도 (50 km/h)
    "depart_lane": "best", # 시작 차선. "best" = 경로상 가장 적합한 차선,
                           # "center" = 가운데 차선, 숫자 = 그 차선
    "depart_speed": 5,     # 시작 속도 (m/s)
    # ego 경로 목록 (출발 도로 id, 도착 도로 id). reset마다 하나를 무작위로 고른다.
    # 기본값: 중앙대로 서면 방면 → 동래 방면 (간선도로 직진 통과)
    "routes": [("SW", "N")],
}

# ──────────────────────────────────────────────────────────────
# 3) 배경 교통류 (SUMO가 알아서 운전하는 일반 차량들)
#    각 도로의 inflow를 나머지 도로로 나눠 보낸다 (도착 도로의 진출 차로 수
#    비율로 배분). 우회전 차량은 우회전 연결로를 이용한다.
# ──────────────────────────────────────────────────────────────
TRAFFIC = {
    "max_speed": 16.0,        # 배경차 공통 기본 최고속도 (m/s).
                              # 실제 속도는 제한속도 × 개체별 속도 편차로 정해진다.
    "depart_speed": "max",    # 신규 차량 진입 속도 ("max" = 안전한 최고속도)

    # ──────────────────────────────────────────────────────
    # 배경차 컨트롤러(차량추종모델) 믹스
    #
    # 실제 도로에는 운전 스타일이 제각각인 차들이 섞여 있다. 배경차를
    # 단일 모델로만 채우면 에이전트가 그 모델의 버릇에 과적합되므로,
    # 서로 다른 SUMO carFollowModel 4종을 확률적으로 섞어 투입한다.
    # (SUMO의 vTypeDistribution 기능 사용 — road_builder.py가 생성)
    #
    # probability: 투입 비율 (합이 1이 아니어도 자동 정규화됨)
    # max_speed  : 컨트롤러별 희망속도 상한 (생략 시 위 공통값)
    # speed_dev  : 같은 타입 안에서도 개체별 희망속도 편차 (0~1)
    # color      : GUI에서 구분용 (ego의 빨강은 피할 것)
    # sigma      : Krauss 계열 전용 "운전자 불완전성" (다른 모델은 무시)
    # ──────────────────────────────────────────────────────
    "controllers": {
        "krauss": {   # 산만한 인간 운전자
            "probability": 0.35,
            "carFollowModel": "Krauss",
            "accel": 2.0, "decel": 4.5,
            "tau": 1.0, "min_gap": 2.5,
            "sigma": 0.3,
            "max_speed": 14.0, "speed_dev": 0.15,
            "color": "1,1,0",    # 노랑
        },
        "idm": {      # 부드러운 표준 인간 모델
            "probability": 0.30,
            "carFollowModel": "IDM",
            "accel": 1.8, "decel": 3.5,
            "tau": 1.2, "min_gap": 2.0,
            "max_speed": 16.0, "speed_dev": 0.10,
            "color": "0,1,1",    # 시안
        },
        "eidm": {     # 반응지연 있는 현실적 인간
            "probability": 0.20,
            "carFollowModel": "EIDM",
            "accel": 2.0, "decel": 4.0,
            "tau": 1.1, "min_gap": 2.0,
            "max_speed": 16.5, "speed_dev": 0.10,
            "color": "1,0.6,0",  # 주황
        },
        "acc": {      # 크루즈 차량
            "probability": 0.15,
            "carFollowModel": "ACC",
            "accel": 2.0, "decel": 4.0,
            "tau": 1.5, "min_gap": 2.0,
            "max_speed": 19.0, "speed_dev": 0.05,
            "color": "1,0,1",    # 마젠타
        },
    },

    # ──────────────────────────────────────────────────────
    # 프리필(pre-fill): 에피소드 시작 시 배경차를 각 진입 도로에 미리 배치
    #
    # flow는 도로 끝(입구)에서만 차를 만들기 때문에, 그냥 시작하면
    # 교차로 주변이 한동안 비어 있다. 프리필은 reset()마다 각 진입 도로에
    # 차량을 일정 간격(± 무작위 흔들림)으로 미리 심어서 첫 스텝부터
    # 교통류 속에서 학습이 이뤄지게 한다. 경로는 그 도로의 flow 비율대로 고른다.
    # ──────────────────────────────────────────────────────
    "prefill": {
        "enabled": True,
        "start_offset": 40,    # ego 출발 도로의 시작 이 구간은 비워둠 (ego 진입 공간)
        "end_margin": 15,      # 진입 도로 끝(분기 지점 앞) 이 구간도 비워둠
        "spacing": None,       # 차선당 배치 간격(m). None이면 도로별 교통량에서
                               # 자동 계산: 제한속도 / (차선당 유량)
        "spacing_jitter": 0.45,  # 간격의 ±45% 무작위 흔들림
    },
}
